function main(input) {
  const m = {};
  for (const it of (input.items || [])) {
    const d = it.data || {};
    const rep = d.rep && String(d.rep).trim() ? String(d.rep).trim() : '(担当者未入力)';
    if (!m[rep]) m[rep] = { rep, visits: 0, prospect: 0 };
    m[rep].visits += Number(d.visits || 0);
    m[rep].prospect += Number(d.prospect || 0);
  }
  const rows = Object.values(m).map(r => ({ week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const lines = rows.map(r => r.rep + ': 訪問 ' + r.visits + ' 件 / 見込み額 ' + r.prospect);
  return { count: rows.length, rows, summary_table: lines.join('\n') };
}

function main(input) {
  const groups = Array.isArray(input.groups) ? input.groups : [];
  const pickNum = (g, re) => { const k = Object.keys(g).find(k => re.test(k) && typeof g[k] === 'number'); return k ? g[k] : 0; };
  const rows = groups.map(g => {
    const rep = g.rep ?? (g.group && g.group.rep) ?? Object.values(g).find(v => typeof v === 'string') ?? '';
    return { week_start: input.start, rep: rep, visits: pickNum(g, /visit/i), prospect: pickNum(g, /prospect/i) };
  });
  const totals = rows.reduce((t, r) => ({ visits: t.visits + r.visits, prospect: t.prospect + r.prospect }), { visits: 0, prospect: 0 });
  const table = rows.map(r => '- ' + r.rep + ': 訪問 ' + r.visits + '件、見込み額 ' + r.prospect + '円').join('\n') || '（先週の日報はありません）';
  return { rows: rows, totals: { visits: totals.visits, prospect: totals.prospect, reps: rows.length }, table: table, week_start: input.start, week_end: input.end };
}

